using System.Security.Cryptography;
using System.Text;

// A GitHub stand-in for the sample cells: it verifies the app JWT the way GitHub's
// verifier does — RS256 signature against the app's public key, plus iss/aud/exp/jti —
// mints a fake installation token, and reports exactly which Authorization the API calls
// carry. Nothing here is a secret: the key pair is generated by the driving fixture.
var builder = WebApplication.CreateBuilder(args);

var signingKeyPem = builder.Configuration["Stub:SigningKey"]
    ?? throw new InvalidOperationException("Stub:SigningKey (the app public key, PEM) is required");
var issuer = builder.Configuration["Stub:Issuer"] ?? "123456";
var audience = builder.Configuration["Stub:Audience"] ?? "https://api.github.com";
var installationToken = builder.Configuration["Stub:InstallationToken"] ?? "ghs_stub_installation";
var signingKey = RSA.Create();
signingKey.ImportFromPem(signingKeyPem);
var tokenEndpointCalls = 0;

var app = builder.Build();

// GitHub's installation-access-tokens endpoint: verify the app JWT, return the token.
app.MapPost("/app/installations/{installationId}/access_tokens", async (HttpContext context) =>
{
    Interlocked.Increment(ref tokenEndpointCalls);

    // GitHub enforces the User-Agent at its administrative edge, before any credential
    // is read: a UA-less request is 403, whatever Authorization it carries (product bug
    // 2026-11-22 — CredProx's token exchange was UA-less and GitHub refused it while
    // every offline cell passed, because this stand-in did not check). The exact GitHub
    // shape, so the offline cells catch the class.
    if (string.IsNullOrWhiteSpace(context.Request.Headers.UserAgent.ToString()))
    {
        context.Response.StatusCode = StatusCodes.Status403Forbidden;
        await context.Response.WriteAsync(
            """{"message":"Request forbidden by administrative rules. Please make sure your request has a User-Agent header."}""");
        return;
    }

    var header = context.Request.Headers.Authorization.ToString();
    var jwt = header.StartsWith("Bearer ", StringComparison.Ordinal) ? header["Bearer ".Length..] : "";
    var parts = jwt.Split('.');

    context.Response.ContentType = "application/json";
    if (jwt.Length == 0 || parts.Length != 3 || !VerifyJwt(signingKey, parts, issuer, audience))
    {
        context.Response.StatusCode = StatusCodes.Status401Unauthorized;
        await context.Response.WriteAsync("""{"message":"Bad credentials"}""");
        return;
    }

    context.Response.StatusCode = StatusCodes.Status201Created;
    await context.Response.WriteAsync(
        $$"""{"token":"{{installationToken}}","expires_at":"{{DateTime.UtcNow.AddHours(1):yyyy-MM-ddTHH:mm:ssZ}}"}""");
});

// A GitHub REST endpoint stand-in: echoes the Authorization it received as JSON — the
// reflecting response the proxy's response scrubber must redact caller-side.
app.Map("/repos/{owner}/{repo}", (HttpContext context) =>
    Results.Json(new { authorization = context.Request.Headers.Authorization.ToString() }));

// Answers "ok" only when the Authorization is byte-exactly the bearer-prefixed
// installation token — the witness that the raw token reached the vendor, which the
// redacted echo cannot show. A mismatch reports only its length, never the value.
app.MapGet("/exact", (HttpContext context) =>
{
    var header = context.Request.Headers.Authorization.ToString();
    return Results.Text(header == $"Bearer {installationToken}" ? "ok" : $"mismatch len={header.Length}", "text/plain");
});

// How many times the token endpoint was called — the cache witness.
app.MapGet("/__calls", () => Results.Text(Volatile.Read(ref tokenEndpointCalls).ToString(), "text/plain"));

app.Run();
return 0;

static bool VerifyJwt(RSA publicKey, string[] parts, string issuer, string audience)
{
    try
    {
        var signingInput = Encoding.ASCII.GetBytes(parts[0] + "." + parts[1]);
        var signature = Convert.FromBase64String(
            parts[2].Replace('-', '+').Replace('_', '/') + new string('=', (4 - parts[2].Length % 4) % 4));
        if (!publicKey.VerifyData(signingInput, signature, HashAlgorithmName.SHA256, RSASignaturePadding.Pkcs1))
        {
            return false;
        }

        var payloadJson = Encoding.UTF8.GetString(Convert.FromBase64String(
            parts[1].Replace('-', '+').Replace('_', '/') + new string('=', (4 - parts[1].Length % 4) % 4)));
        using var payload = System.Text.Json.JsonDocument.Parse(payloadJson);
        var root = payload.RootElement;
        return root.GetProperty("iss").GetString() == issuer
            && root.GetProperty("aud").GetString() == audience
            && root.GetProperty("exp").GetInt64() > DateTimeOffset.UtcNow.ToUnixTimeSeconds()
            && !string.IsNullOrEmpty(root.GetProperty("jti").GetString());
    }
    catch (Exception ex) when (ex is CryptographicException or FormatException or System.Text.Json.JsonException or InvalidOperationException)
    {
        return false;
    }
}
